language: python
version: 0.2.0
status: defined_not_executed
entrypoint: process_event_or_reconcile
dependency: fastembed
autoInstallIfMissing: true
installSpecSource: configuration FASTEMBED_INSTALL_SPEC, default fastembed
networkPolicy: denied in steady state; temporarily allowed only for missing-dependency bootstrap
filesystemPolicy: Python environment package installation only during authorized bootstrap
graphWritePolicy: changeset_only
source: |
  from __future__ import annotations

  import hashlib
  import importlib
  import importlib.metadata
  import json
  import math
  import os
  import subprocess
  import sys
  from dataclasses import dataclass
  from datetime import datetime, timezone
  from typing import Any, Iterable

  SEMANTIC_FIELDS = ("id", "node_type", "subtype", "name", "synthesis", "content")
  DERIVED_EMBEDDING_FIELDS = {
      "embeddingVector", "embeddingModelId", "embeddingModelRevision",
      "embeddingDimension", "embeddingContentHash", "embeddingUpdatedAt",
      "embeddingStatus", "embeddingError", "embeddingPackageVersion"
  }
  EVENT_EMBED = {"node_created", "node_changed"}
  EVENT_HEALTH = {"periodic_embedding_health_check", "dependency_changed"}
  EVENT_INCREMENTAL = {"periodic_embedding_reconciliation", "manual_embedding_backfill"}
  EVENT_FULL = {"periodic_embedding_full_reconciliation", "embedding_model_changed"}

  @dataclass(frozen=True)
  class EmbedConfig:
      model_id: str
      model_revision: str
      expected_dimension: int | None = None
      batch_size: int = 64
      auto_install: bool = True
      install_spec: str = os.getenv("FASTEMBED_INSTALL_SPEC", "fastembed")

  def utc_now() -> str:
      return datetime.now(timezone.utc).isoformat()

  def ensure_fastembed(config: EmbedConfig, audit: Any):
      try:
          module = importlib.import_module("fastembed")
          return module, importlib.metadata.version("fastembed"), False
      except ModuleNotFoundError:
          if not config.auto_install:
              raise RuntimeError("fastembed_missing_and_auto_install_disabled")

      audit.write_raw_run({
          "kind": "DependencyBootstrapRun",
          "packageSpec": config.install_spec,
          "startedAt": utc_now(),
          "networkTemporarilyAllowed": True,
      })
      command = [
          sys.executable, "-m", "pip", "install",
          "--disable-pip-version-check", "--no-input", config.install_spec,
      ]
      completed = subprocess.run(command, capture_output=True, text=True, check=False)
      audit.write_raw_run({
          "kind": "DependencyBootstrapResult",
          "packageSpec": config.install_spec,
          "returnCode": completed.returncode,
          "stdoutTail": completed.stdout[-4000:],
          "stderrTail": completed.stderr[-4000:],
          "completedAt": utc_now(),
      })
      if completed.returncode != 0:
          raise RuntimeError(f"fastembed_install_failed:{completed.returncode}")

      importlib.invalidate_caches()
      module = importlib.import_module("fastembed")
      version = importlib.metadata.version("fastembed")
      return module, version, True

  def canonical_semantic_text(node: dict[str, Any]) -> str:
      payload = {key: node.get(key) for key in SEMANTIC_FIELDS}
      return json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":"))

  def semantic_hash(node: dict[str, Any]) -> str:
      return hashlib.sha256(canonical_semantic_text(node).encode("utf-8")).hexdigest()

  def is_embedding_only_change(event: dict[str, Any]) -> bool:
      changed = set(event.get("changedFields") or [])
      return bool(changed) and changed.issubset(DERIVED_EMBEDDING_FIELDS)

  def requires_embedding(node: dict[str, Any], config: EmbedConfig) -> bool:
      expected_hash = semantic_hash(node)
      return any((
          node.get("embeddingStatus") != "measured",
          node.get("embeddingContentHash") != expected_hash,
          node.get("embeddingModelId") != config.model_id,
          node.get("embeddingModelRevision") != config.model_revision,
          not node.get("embeddingVector"),
      ))

  def validate_vector(vector: list[float], expected_dimension: int | None) -> None:
      if not vector:
          raise ValueError("empty_embedding")
      if expected_dimension is not None and len(vector) != expected_dimension:
          raise ValueError(f"wrong_embedding_dimension:{len(vector)}")
      if any(not math.isfinite(float(value)) for value in vector):
          raise ValueError("non_finite_embedding_value")

  def embed_nodes(nodes: list[dict[str, Any]], config: EmbedConfig, graph: Any, audit: Any) -> dict[str, Any]:
      fastembed, package_version, installed_now = ensure_fastembed(config, audit)
      model = fastembed.TextEmbedding(model_name=config.model_id)
      candidates = [node for node in nodes if requires_embedding(node, config)]
      embedded = failed = 0

      for start in range(0, len(candidates), config.batch_size):
          batch = candidates[start:start + config.batch_size]
          texts = [canonical_semantic_text(node) for node in batch]
          try:
              vectors: Iterable[Any] = model.embed(texts)
              patches = []
              for node, raw_vector in zip(batch, vectors):
                  vector = [float(value) for value in raw_vector]
                  validate_vector(vector, config.expected_dimension)
                  patches.append({
                      "nodeId": node["id"],
                      "derivedProperties": {
                          "embeddingVector": vector,
                          "embeddingModelId": config.model_id,
                          "embeddingModelRevision": config.model_revision,
                          "embeddingDimension": len(vector),
                          "embeddingContentHash": semantic_hash(node),
                          "embeddingUpdatedAt": utc_now(),
                          "embeddingStatus": "measured",
                          "embeddingError": None,
                          "embeddingPackageVersion": package_version,
                      },
                  })
              graph.submit_changeset(
                  kind="derived_embedding_update",
                  idempotency_key=hashlib.sha256(json.dumps(patches, sort_keys=True).encode()).hexdigest(),
                  patches=patches,
                  semantic_revision_change=False,
              )
              embedded += len(patches)
          except Exception as exc:
              failed += len(batch)
              audit.write_raw_run({
                  "kind": "EmbeddingBatchFailure",
                  "nodeIds": [node["id"] for node in batch],
                  "informationStatus": "measurement_failed",
                  "error": repr(exc),
                  "at": utc_now(),
              })

      result = {
          "kind": "EmbeddingRun",
          "packageVersion": package_version,
          "dependencyInstalledDuringRun": installed_now,
          "candidateCount": len(candidates),
          "embeddedCount": embedded,
          "failedCount": failed,
          "informationStatus": "measured" if failed == 0 else "measurement_failed",
          "completedAt": utc_now(),
      }
      audit.write_raw_run(result)
      return result

  def periodic_health_check(config: EmbedConfig, graph: Any, audit: Any) -> dict[str, Any]:
      try:
          fastembed, package_version, installed_now = ensure_fastembed(config, audit)
          model = fastembed.TextEmbedding(model_name=config.model_id)
          probe = [float(v) for v in next(iter(model.embed(["embedding health probe"])))]
          validate_vector(probe, config.expected_dimension)
          counts = graph.count_embedding_states(config.model_id, config.model_revision)
          result = {
              "kind": "EmbeddingHealthCheck",
              "dependencyImport": "measured_present",
              "packageVersion": package_version,
              "installedDuringCheck": installed_now,
              "modelLoad": "measured_present",
              "probeDimension": len(probe),
              "coverage": counts,
              "informationStatus": "measured",
              "checkedAt": utc_now(),
          }
      except Exception as exc:
          result = {
              "kind": "EmbeddingHealthCheck",
              "informationStatus": "measurement_failed",
              "error": repr(exc),
              "checkedAt": utc_now(),
          }
      audit.write_raw_run(result)
      return result

  def process_event_or_reconcile(event: dict[str, Any], config: EmbedConfig, graph: Any, audit: Any):
      event_type = event.get("eventType")
      if event_type in EVENT_EMBED:
          if event_type == "node_changed" and is_embedding_only_change(event):
              return {"status": "ignored_embedding_only_change"}
          node = graph.get_node(event["nodeId"])
          return embed_nodes([node], config, graph, audit)
      if event_type in EVENT_HEALTH:
          return periodic_health_check(config, graph, audit)
      if event_type in EVENT_INCREMENTAL:
          nodes = graph.iter_nodes_missing_or_stale_embeddings(config.model_id, config.model_revision)
          return embed_nodes(list(nodes), config, graph, audit)
      if event_type in EVENT_FULL:
          nodes = graph.iter_all_nodes()
          return embed_nodes(list(nodes), config, graph, audit)
      return {"status": "ignored_unknown_event", "eventType": event_type}

Fixtures requises:
- node créée sans embedding puis mesurée;
- modification de name, synthesis et content déclenchant un nouveau hash;
- modification embedding-only ne déclenchant aucun nouveau calcul;
- même événement reçu deux fois produisant un seul ChangeSet effectif;
- changement de modèle rendant toutes les anciennes projections stale;
- node historique sans vecteur retrouvée par réconciliation;
- batch partiellement échoué conservant les résultats réussis et les erreurs attribuées;
- vecteur vide, dimension incorrecte, NaN ou infini rejetés;
- contenu Unicode et mappings ordonnés produisant un hash déterministe;
- aucune mutation du contenu sémantique ni de sa révision;
- runtime sans fastembed produisant unavailable ou measurement_failed, jamais healthy.

observes: toutes les nodes accessibles et la configuration active du modèle
triggers: embedding_run_completed, embedding_model_changed, periodic_health_tick, manual_audit
procedure:
  - compter toutes les nodes éligibles;
  - vérifier présence du vecteur et des métadonnées;
  - recalculer SemanticContentHash sans utiliser les champs embedding_*;
  - comparer hash et identité du modèle;
  - classifier measured, missing, stale, measurement_failed ou unknown;
  - mesurer latence depuis création ou dernier changement sémantique;
  - échantillonner des vectors pour dimension et valeurs finies.
output: EmbeddingCoverageRun brut, sans conclusion de health incorporée.

