source: |
  export type Provenance = {
    kind: "protocol" | "external_constraint" | "measurement" | "experiment" | "configuration" | "decision";
    sourceId: string;
    version?: string;
  };

  export type ScriptEffect =
    | {
        kind: "schedule";
        mechanism: "deadline_moment" | "citizen_alarm" | "state_change" | "cron" | "interval" | "polling";
        evidenceRef: string;
        exceptionJustificationId?: string;
      }
    | {
        kind: "network";
        mode: "capability" | "connector" | "membrane" | "trusted_adapter" | "direct";
        evidenceRef: string;
        authorityId?: string;
        exceptionJustificationId?: string;
      };
    | {
        kind: "other";
        evidenceRef: string;
      };

  export type DecisionParameter = {
    name: string;
    value: unknown;
    affectsBehavior: boolean;
    evidenceRef: string;
    provenance?: Provenance;
    declaredExperimental?: boolean;
    exceptionJustificationId?: string;
  };

  export type ScriptRevision = {
    scriptId: string;
    semanticType: "Script";
    revision: string;
    sourceHash: string;
    effects: ScriptEffect[];
    parameters: DecisionParameter[];
  };

  export type AntipatternCandidate = {
    antipatternId: "AP-001-A" | "AP-001-B" | "AP-001-C";
    scriptId: string;
    revision: string;
    sourceHash: string;
    evidenceRef: string;
    epistemicStatus: "candidate";
    requestedAction: "justify_or_refactor";
  };

  export function scanScriptRevision(script: ScriptRevision): AntipatternCandidate[] {
    const candidates: AntipatternCandidate[] = [];

    for (const effect of script.effects) {
      if (
        effect.kind === "schedule" &&
        ["cron", "interval", "polling"].includes(effect.mechanism) &&
        !effect.exceptionJustificationId
      ) {
        candidates.push(candidate("AP-001-A", script, effect.evidenceRef));
      }

      if (
        effect.kind === "network" &&
        effect.mode === "direct" &&
        !effect.exceptionJustificationId
      ) {
        candidates.push(candidate("AP-001-B", script, effect.evidenceRef));
      }
    }

    for (const parameter of script.parameters) {
      if (
        parameter.affectsBehavior &&
        !parameter.provenance &&
        !parameter.declaredExperimental &&
        !parameter.exceptionJustificationId
      ) {
        candidates.push(candidate("AP-001-C", script, parameter.evidenceRef));
      }
    }

    return candidates;
  }

  function candidate(
    antipatternId: AntipatternCandidate["antipatternId"],
    script: ScriptRevision,
    evidenceRef: string,
  ): AntipatternCandidate {
    return {
      antipatternId,
      scriptId: script.scriptId,
      revision: script.revision,
      sourceHash: script.sourceHash,
      evidenceRef,
      epistemicStatus: "candidate",
      requestedAction: "justify_or_refactor",
    };
  }
notes: |
  Le scanner ne recherche pas naïvement tous les nombres ni tous les mots cron/API. Il inspecte une représentation structurée des effets et paramètres du Script. Une extraction statique source-vers-IR peut être fournie par une Capability enregistrée et auditée. La création idempotente du Moment est effectuée par le writer du Trusted Kernel à partir de scriptId, sourceHash, antipatternId et evidenceRef.

