  export type ImpulseInput = { energy:number; weight:number; polarity:number; gate:number; clampMin:number; clampMax:number };
  export type ImpulseResult = { raw:number; value:number; factors:ImpulseInput; status:'measured'|'measurement_failed' };
  export function computeImpulse(x:ImpulseInput):ImpulseResult {
    const values=[x.energy,x.weight,x.polarity,x.gate,x.clampMin,x.clampMax];
    if(values.some(v=>!Number.isFinite(v))) return {raw:NaN,value:NaN,factors:x,status:'measurement_failed'};
    const raw=x.energy*x.weight*x.polarity*x.gate;
    const value=Math.min(x.clampMax,Math.max(x.clampMin,raw));
    return {raw,value,factors:x,status:'measured'};
  }
effects: none

