  export type EnergyEvent={id:string;value:number};
  export type EnergyInput={current:number;baseline:number;decayRate:number;events:EnergyEvent[];min:number;max:number};
  export function integrateEnergy(x:EnergyInput){
    const unique=[...new Map(x.events.map(e=>[e.id,e])).values()].sort((a,b)=>a.id.localeCompare(b.id));
    if(![x.current,x.baseline,x.decayRate,x.min,x.max,...unique.map(e=>e.value)].every(Number.isFinite)) return {status:'measurement_failed' as const};
    const injected=unique.reduce((s,e)=>s+e.value,0);
    const raw=(1-x.decayRate)*x.current+injected;
    const value=Math.min(x.max,Math.max(x.min,Math.max(x.baseline,raw)));
    return {status:'measured' as const,value,raw,injected,eventIds:unique.map(e=>e.id)};
  }
