  export type GateDecision={decision:'allow'|'deny'|'require_human';coefficient?:number;valid:boolean;expired:boolean;revoked:boolean;reasonCodes:string[]};
  export function evaluateGate(d:GateDecision|undefined,required:boolean){
    if(!required) return {status:'measured' as const,gate:1,reasonCodes:['gate_not_required']};
    if(!d) return {status:'known_absent' as const,gate:0,reasonCodes:['missing_gate_decision']};
    if(!d.valid||d.expired||d.revoked) return {status:'measured' as const,gate:0,reasonCodes:[...d.reasonCodes,'invalid_or_stale']};
    if(d.decision!=='allow') return {status:'measured' as const,gate:0,reasonCodes:d.reasonCodes};
    const g=d.coefficient??1;
    if(!Number.isFinite(g)||g<0||g>1) return {status:'measurement_failed' as const,gate:0,reasonCodes:['invalid_gate_domain']};
    return {status:'measured' as const,gate:g,reasonCodes:d.reasonCodes};
  }
