  from __future__ import annotations

  import hashlib
  import os
  import subprocess
  from dataclasses import dataclass
  from pathlib import Path, PurePosixPath
  from typing import Any, Iterable, Protocol

  POLICY_VERSION = "0.1.0"
  AUDIT_LOOP_ID = "space:l2:repo-file-loop-coverage-v0"
  ACCEPTED_COVERAGE_RELATIONS = (
      "COVERED_BY_LOOP", "IMPLEMENTS", "MATERIALIZES", "PART_OF"
  )

  @dataclass(frozen=True)
  class RepositoryFile:
      repository_id: str
      relative_path: str
      absolute_path: Path
      digest_sha256: str
      size_bytes: int
      git_state: str
      entry_kind: str

  class GraphPort(Protocol):
      def resolve_repository_file(
          self, repository_id: str, relative_path: str
      ) -> dict[str, Any] | None: ...

      def active_coverage_loop_ids(
          self,
          file_node_id: str,
          relations: tuple[str, ...],
          excluded_loop_id: str,
      ) -> list[str]: ...

      def list_repository_file_nodes(
          self, repository_id: str
      ) -> Iterable[dict[str, Any]]: ...

      def apply_changeset(
          self, idempotency_key: str, operations: list[dict[str, Any]]
      ) -> str: ...

  def _git(root: Path, *args: str) -> bytes:
      completed = subprocess.run(
          ["git", "-C", str(root), *args],
          check=True,
          stdout=subprocess.PIPE,
          stderr=subprocess.PIPE,
      )
      return completed.stdout

  def _nul_paths(raw: bytes) -> set[str]:
      result: set[str] = set()
      for item in raw.split(b"\0"):
          if not item:
              continue
          result.add(item.decode("utf-8", errors="surrogateescape"))
      return result

  def _safe_relative_path(value: str) -> str:
      path = PurePosixPath(value.replace("\\", "/"))
      if path.is_absolute() or not path.parts or ".." in path.parts:
          raise ValueError(f"unsafe repository path: {value!r}")
      return path.as_posix()

  def _sha256_entry(path: Path, relative_path: str) -> tuple[str, int, str]:
      stat = path.lstat()
      digest = hashlib.sha256()
      if path.is_symlink():
          target = os.readlink(path)
          encoded = target.encode("utf-8", errors="surrogateescape")
          digest.update(b"symlink\0" + encoded)
          return digest.hexdigest(), len(encoded), "symlink"
      if path.is_file():
          with path.open("rb") as handle:
              for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                  digest.update(chunk)
          return digest.hexdigest(), stat.st_size, "file"
      # Gitlinks are represented by directory paths in the working tree.
      encoded = relative_path.encode("utf-8", errors="surrogateescape")
      digest.update(b"gitlink-or-directory\0" + encoded)
      return digest.hexdigest(), 0, "gitlink_or_directory"

  def enumerate_repository_files(
      repository_root: str | Path, repository_id: str
  ) -> list[RepositoryFile]:
      requested_root = Path(repository_root).resolve()
      canonical_root = Path(
          _git(requested_root, "rev-parse", "--show-toplevel")
          .decode("utf-8", errors="strict")
          .strip()
      ).resolve()
      tracked = _nul_paths(_git(canonical_root, "ls-files", "--cached", "-z"))
      untracked = _nul_paths(
          _git(canonical_root, "ls-files", "--others", "--exclude-standard", "-z")
      )
      records: list[RepositoryFile] = []
      for raw_path in sorted(tracked | untracked):
          relative_path = _safe_relative_path(raw_path)
          full_path = canonical_root.joinpath(*PurePosixPath(relative_path).parts)
          # Lexical path safety; symlinks are hashed without following them.
          if canonical_root not in full_path.parents and full_path != canonical_root:
              raise ValueError(f"path escaped repository: {relative_path}")
          digest, size, entry_kind = _sha256_entry(full_path, relative_path)
          records.append(
              RepositoryFile(
                  repository_id=repository_id,
                  relative_path=relative_path,
                  absolute_path=full_path,
                  digest_sha256=digest,
                  size_bytes=size,
                  git_state="tracked" if raw_path in tracked else "untracked_not_ignored",
                  entry_kind=entry_kind,
              )
          )
      return records

  def _identity(repository_id: str, relative_path: str) -> str:
      payload = f"{repository_id}\0{relative_path}".encode("utf-8")
      return hashlib.sha256(payload).hexdigest()

  def _file_node_id(repository_id: str, relative_path: str) -> str:
      return f"thing:repository-file:{_identity(repository_id, relative_path)}"

  def _warning_id(repository_id: str, relative_path: str) -> str:
      payload = (
          f"{repository_id}\0{relative_path}\0{POLICY_VERSION}"
      ).encode("utf-8")
      return f"warning:repo-file-loop-coverage:{hashlib.sha256(payload).hexdigest()}"

  def _file_node_operation(record: RepositoryFile, node_id: str) -> dict[str, Any]:
      return {
          "op": "upsert_node",
          "node": {
              "id": node_id,
              "node_type": "thing",
              "subtype": "repository_file",
              "name": f"Repository file · {record.relative_path}",
              "content": {
                  "repositoryId": record.repository_id,
                  "relativePath": record.relative_path,
                  "sha256": record.digest_sha256,
                  "sizeBytes": record.size_bytes,
                  "gitState": record.git_state,
                  "entryKind": record.entry_kind,
                  "repositoryPresence": "measured_present",
                  "coverageStatus": "unresolved",
                  "generatedBy": AUDIT_LOOP_ID,
              },
          },
      }

  def _warning_operation(record: RepositoryFile, file_node_id: str) -> dict[str, Any]:
      return {
          "op": "upsert_node",
          "node": {
              "id": _warning_id(record.repository_id, record.relative_path),
              "node_type": "narrative",
              "subtype": "warning",
              "name": f"Fichier sans loop · {record.relative_path}",
              "content": {
                  "status": "open",
                  "reasonCode": "REPOSITORY_FILE_WITHOUT_ACTIVE_LOOP",
                  "repositoryId": record.repository_id,
                  "relativePath": record.relative_path,
                  "fileNodeId": file_node_id,
                  "acceptedCoverageRelations": list(ACCEPTED_COVERAGE_RELATIONS),
                  "nextAction": "Relier la node fichier à la SelfVerifyingLoop métier correcte.",
                  "autoAssignmentForbidden": True,
                  "policyVersion": POLICY_VERSION,
              },
          },
          "links": [
              {"source": _warning_id(record.repository_id, record.relative_path), "type": "WARNS_ABOUT", "target": file_node_id},
              {"source": _warning_id(record.repository_id, record.relative_path), "type": "GENERATED_BY", "target": AUDIT_LOOP_ID},
          ],
      }

  def reconcile_repository(
      repository_root: str | Path,
      repository_id: str,
      graph: GraphPort,
      batch_limit: int = 200,
  ) -> dict[str, int]:
      if batch_limit < 1:
          raise ValueError("batch_limit must be positive")
      records = enumerate_repository_files(repository_root, repository_id)
      current_paths = {record.relative_path for record in records}
      counters = {"scoped": len(records), "nodes_created": 0, "warnings_opened": 0, "warnings_resolved": 0, "tombstoned": 0}
      pending: list[dict[str, Any]] = []

      def commit(key_suffix: str) -> None:
          nonlocal pending
          if not pending:
              return
          digest = hashlib.sha256(
              f"{repository_id}\0{POLICY_VERSION}\0{key_suffix}".encode("utf-8")
          ).hexdigest()
          graph.apply_changeset(f"repo-file-loop-coverage:{digest}", pending)
          pending = []

      for index, record in enumerate(records):
          existing = graph.resolve_repository_file(repository_id, record.relative_path)
          file_node_id = existing["id"] if existing else _file_node_id(repository_id, record.relative_path)
          pending.append(_file_node_operation(record, file_node_id))
          if existing is None:
              counters["nodes_created"] += 1
          covered_by = graph.active_coverage_loop_ids(
              file_node_id, ACCEPTED_COVERAGE_RELATIONS, AUDIT_LOOP_ID
          )
          if covered_by:
              pending.append({
                  "op": "resolve_warning",
                  "warning_id": _warning_id(repository_id, record.relative_path),
                  "resolution": {"status": "resolved", "coveredBy": covered_by},
              })
              counters["warnings_resolved"] += 1
          else:
              pending.append(_warning_operation(record, file_node_id))
              counters["warnings_opened"] += 1
          if len(pending) >= batch_limit:
              commit(f"files-through-{index}")

      for stale in graph.list_repository_file_nodes(repository_id):
          relative_path = stale.get("relativePath") or stale.get("content", {}).get("relativePath")
          if relative_path and relative_path not in current_paths:
              pending.append({
                  "op": "patch_node",
                  "node_id": stale["id"],
                  "patch": {"repositoryPresence": "known_absent", "coverageStatus": "not_applicable_out_of_scope"},
              })
              pending.append({
                  "op": "resolve_warning",
                  "warning_id": _warning_id(repository_id, relative_path),
                  "resolution": {"status": "resolved", "reason": "file_out_of_git_scope"},
              })
              counters["tombstoned"] += 1
              if len(pending) >= batch_limit:
                  commit(f"tombstone-{counters['tombstoned']}")

      commit("final")
      return counters

