semanticType: CodeDefinition
authorityMode: graph_structured_definition
language: typescript
version: 0.1.0
evaluatorType: pure_compiler
inputs: VisualizationProfile, AudienceProfile, AuthorizedSubgraph
output: ProjectionSpec | contract_incomplete | permission_denied | unsupported_encoding
effects: none
forbidden: network, filesystem, cron, polling, graph mutation, hidden defaults, invented relations
invariants:
  - output nodes and edges are subsets of the authorized input graph
  - every critical encoding has a VisualJustification
  - unknown is never rendered as zero
  - interaction requires a real affordance
  - declared losses are preserved
source: |
  export function compileProjection(profile, graph) {
    if (!profile?.question || !profile?.audience || !profile?.selection || !profile?.encoding) {
      return { status: "contract_incomplete" };
    }
    const nodes = selectAuthorizedNodes(profile.selection, graph);
    const edges = selectAuthorizedEdges(profile.selection, nodes, graph);
    validateVisualJustifications(profile.encoding, profile.visualJustifications);
    validateAffordances(profile.interactions, graph.affordances);
    return {
      status: "measured",
      question: profile.question,
      audience: profile.audience,
      nodes, edges,
      encoding: profile.encoding,
      inspectionOrder: profile.inspectionOrder,
      interactions: profile.interactions,
      declaredLosses: profile.declaredLosses,
      criticalMisinterpretations: profile.criticalMisinterpretations
    };
  }

status: defined_not_runtime_executed
evaluatorType: independent_projection_roundtrip
inputs: VisualizationProfile, AuthorizedSubgraph, ProjectionSpec, renderedAccessibilityTree optional
procedure:
  - comparer nodes et edges projetés au sous-graphe autorisé;
  - vérifier mappings propriété-canal;
  - vérifier présence des justifications visuelles critiques;
  - vérifier pertes et criticalMisinterpretations;
  - vérifier qu'aucune interaction sans affordance n'est rendue;
  - vérifier conservation des statuts épistémiques;
  - si arbre d'accessibilité fourni, vérifier labels et alternatives non chromatiques.
